333: 			dmn->dmn_events &= (uint32_t)~EPOLLIN;
334: 		}
335: 	}
336: 	if (LIST_EMPTY(&dmn->dmn_writers_head)) {
337: 		events &= (uint32_t)~EPOLLOUT;
338: 		if (dmn->dmn_disarmed_events & EPOLLOUT) {
339: 			dmn->dmn_disarmed_events &= (uint16_t)~EPOLLOUT;
340: 			dmn->dmn_events &= (uint32_t)~EPOLLOUT;
341: 		}
342: 	}
343: 
344: 	if (events & (EPOLLIN | EPOLLOUT)) {
345: 		if (events != _dispatch_muxnote_armed_events(dmn)) {
346: 			dmn->dmn_events = events;
347: 			events = _dispatch_muxnote_armed_events(dmn);
348: 			_dispatch_epoll_update(dmn, events, EPOLL_CTL_MOD);
349: 		}
