374: static void
375: _dispatch_timeout_program(uint32_t tidx, uint64_t target,
376: 		DISPATCH_UNUSED uint64_t leeway)
377: {
378: 	dispatch_clock_t clock = DISPATCH_TIMER_CLOCK(tidx);
379: 	dispatch_epoll_timeout_t timer = &_dispatch_epoll_timeout[clock];
380: 	struct epoll_event ev = {
381: 		.events = EPOLLONESHOT | EPOLLIN,
382: 
383: 	};
384: 	int op;
385: 
386: 	if (target >= INT64_MAX && !timer->det_registered) {
387: 		return;
388: 	}
389: 	ev.data.u32 = timer->det_ident;
390: 
391: 	if (unlikely(timer->det_fd < 0)) {
392: 		clockid_t clockid;
393: 		int fd;
394: 		switch (DISPATCH_TIMER_CLOCK(tidx)) {
395: 		case DISPATCH_CLOCK_UPTIME:
396: 			clockid = CLOCK_MONOTONIC;
397: 			break;
398: 		case DISPATCH_CLOCK_MONOTONIC:
399: 			clockid = CLOCK_BOOTTIME;
400: 			break;
401: 		case DISPATCH_CLOCK_WALL:
402: 			clockid = CLOCK_REALTIME;
403: 			break;
404: 		}
405: 		fd = timerfd_create(clockid, TFD_NONBLOCK | TFD_CLOEXEC);
406: 		if (!dispatch_assume(fd >= 0)) {
407: 			return;
408: 		}
409: 		timer->det_fd = fd;
410: 	}
411: 
412: 	if (target < INT64_MAX) {
413: 		struct itimerspec its = { .it_value = {
414: 			.tv_sec  = (time_t)(target / NSEC_PER_SEC),
415: 			.tv_nsec = target % NSEC_PER_SEC,
416: 		} };
417: 		dispatch_assume_zero(timerfd_settime(timer->det_fd, TFD_TIMER_ABSTIME,
418: 				&its, NULL));
419: 		if (!timer->det_registered) {
420: 			op = EPOLL_CTL_ADD;
421: 		} else if (!timer->det_armed) {
422: 			op = EPOLL_CTL_MOD;
423: 		} else {
424: 			return;
425: 		}
426: 	} else {
427: 		op = EPOLL_CTL_DEL;
428: 	}
429: 	dispatch_assume_zero(epoll_ctl(_dispatch_epfd, op, timer->det_fd, &ev));
430: 	timer->det_armed = timer->det_registered = (op != EPOLL_CTL_DEL);;
431: }
