495: static void
496: _dispatch_event_merge_signal(dispatch_muxnote_t dmn)
497: {
498: 	dispatch_unote_linkage_t dul, dul_next;
499: 	struct signalfd_siginfo si;
500: 	ssize_t rc;
501: 
502: 	// Linux has the weirdest semantics around signals: if it finds a thread
503: 	// that has not masked a process wide-signal, it may deliver it to this
504: 	// thread, meaning that the signalfd may have been made readable, but the
505: 	// signal consumed through the legacy delivery mechanism.
506: 	//
507: 	// Because of this we can get a misfire of the signalfd yielding EAGAIN the
508: 	// first time around. The _dispatch_muxnote_signal_block_and_raise() hack
509: 	// will kick in, the thread with the wrong mask will be fixed up, and the
510: 	// signal delivered to us again properly.
511: 	if ((rc = read(dmn->dmn_fd, &si, sizeof(si))) == sizeof(si)) {
512: 		LIST_FOREACH_SAFE(dul, &dmn->dmn_readers_head, du_link, dul_next) {
513: 			dispatch_unote_t du = _dispatch_unote_linkage_get_unote(dul);
514: 			// consumed by dux_merge_evt()
515: 			_dispatch_retain_unote_owner(du);
516: 			dispatch_assert(!dux_needs_rearm(du._du));
517: 			os_atomic_store2o(du._dr, ds_pending_data, 1, relaxed);
518: 			dux_merge_evt(du._du, EV_ADD|EV_ENABLE|EV_CLEAR, 1, 0);
519: 		}
520: 	} else {
521: 		dispatch_assume(rc == -1 && errno == EAGAIN);
522: 	}
523: }
