525: static uintptr_t
526: _dispatch_get_buffer_size(dispatch_muxnote_t dmn, bool writer)
527: {
528: 	int n;
529: 
530: 	if (writer ? dmn->dmn_skip_outq_ioctl : dmn->dmn_skip_inq_ioctl) {
531: 		return 1;
532: 	}
533: 
534: 	if (ioctl((int)dmn->dmn_ident, writer ? SIOCOUTQ : SIOCINQ, &n) != 0) {
535: 		switch (errno) {
536: 		case EINVAL:
537: 		case ENOTTY:
538: 			// this file descriptor actually doesn't support the buffer
539: 			// size ioctl, remember that for next time to avoid the syscall.
540: 			break;
541: 		default:
542: 			dispatch_assume_zero(errno);
543: 			break;
544: 		}
545: 		if (writer) {
546: 			dmn->dmn_skip_outq_ioctl = true;
547: 		} else {
548: 			dmn->dmn_skip_inq_ioctl = true;
549: 		}
550: 		return 1;
551: 	}
552: 	return (uintptr_t)n;
553: }
