555: static void
556: _dispatch_event_merge_hangup(dispatch_unote_t du)
557: {
558: 	// consumed by dux_merge_evt()
559: 	_dispatch_retain_unote_owner(du);
560: 	dispatch_unote_state_t du_state = _dispatch_unote_state(du);
561: 	du_state |= DU_STATE_NEEDS_DELETE;
562: 	du_state &= ~DU_STATE_ARMED;
563: 	_dispatch_unote_state_set(du, du_state);
564: 	uintptr_t data = 0;  // EOF
565: 	os_atomic_store2o(du._dr, ds_pending_data, ~data, relaxed);
566: 	dux_merge_evt(du._du, EV_DELETE|EV_DISPATCH, data, 0);
567: }
