569: static void
570: _dispatch_event_merge_fd(dispatch_muxnote_t dmn, uint32_t events)
571: {
572: 	dispatch_unote_linkage_t dul, dul_next;
573: 	uintptr_t data;
574: 
575: 	dmn->dmn_disarmed_events |= (events & (EPOLLIN | EPOLLOUT));
576: 
577: 	if (events & EPOLLIN) {
578: 		data = _dispatch_get_buffer_size(dmn, false);
579: 		LIST_FOREACH_SAFE(dul, &dmn->dmn_readers_head, du_link, dul_next) {
580: 			dispatch_unote_t du = _dispatch_unote_linkage_get_unote(dul);
581: 			// consumed by dux_merge_evt()
582: 			_dispatch_retain_unote_owner(du);
583: 			dispatch_assert(dux_needs_rearm(du._du));
584: 			_dispatch_unote_state_clear_bit(du, DU_STATE_ARMED);
585: 			os_atomic_store2o(du._dr, ds_pending_data, ~data, relaxed);
586: 			dux_merge_evt(du._du, EV_ADD|EV_ENABLE|EV_DISPATCH, data, 0);
587: 		}
588: 	}
589: 
590: 	if (events & EPOLLOUT) {
591: 		data = _dispatch_get_buffer_size(dmn, true);
592: 		LIST_FOREACH_SAFE(dul, &dmn->dmn_writers_head, du_link, dul_next) {
593: 			dispatch_unote_t du = _dispatch_unote_linkage_get_unote(dul);
594: 			// consumed by dux_merge_evt()
595: 			_dispatch_retain_unote_owner(du);
596: 			dispatch_assert(dux_needs_rearm(du._du));
597: 			_dispatch_unote_state_clear_bit(du, DU_STATE_ARMED);
598: 			os_atomic_store2o(du._dr, ds_pending_data, ~data, relaxed);
599: 			dux_merge_evt(du._du, EV_ADD|EV_ENABLE|EV_DISPATCH, data, 0);
600: 		}
601: 	}
602: 
603: 	// SR-9033: EPOLLHUP is an unmaskable event which we must respond to
604: 	if (events & EPOLLHUP) {
605: 		LIST_FOREACH_SAFE(dul, &dmn->dmn_readers_head, du_link, dul_next) {
606: 			dispatch_unote_t du = _dispatch_unote_linkage_get_unote(dul);
607: 			_dispatch_event_merge_hangup(du);
608: 		}
609: 		LIST_FOREACH_SAFE(dul, &dmn->dmn_writers_head, du_link, dul_next) {
610: 			dispatch_unote_t du = _dispatch_unote_linkage_get_unote(dul);
611: 			_dispatch_event_merge_hangup(du);
612: 		}
613: 		epoll_ctl(_dispatch_epfd, EPOLL_CTL_DEL, dmn->dmn_fd, NULL);
614: 		return;
615: 	}
616: 
617: 	events = _dispatch_muxnote_armed_events(dmn);
618: 	if (events) _dispatch_epoll_update(dmn, events, EPOLL_CTL_MOD);
619: }
