622: void
623: _dispatch_event_loop_drain(uint32_t flags)
624: {
625: 	struct epoll_event ev[DISPATCH_EPOLL_MAX_EVENT_COUNT];
626: 	int i, r;
627: 	int timeout = (flags & KEVENT_FLAG_IMMEDIATE) ? 0 : -1;
628: 
629: retry:
630: 	r = epoll_wait(_dispatch_epfd, ev, countof(ev), timeout);
631: 	if (unlikely(r == -1)) {
632: 		int err = errno;
633: 		switch (err) {
634: 		case EINTR:
635: 			goto retry;
636: 		case EBADF:
637: 			DISPATCH_CLIENT_CRASH(err, "Do not close random Unix descriptors");
638: 			break;
639: 		default:
640: 			(void)dispatch_assume_zero(err);
641: 			break;
642: 		}
643: 		return;
644: 	}
645: 
646: 	for (i = 0; i < r; i++) {
647: 		dispatch_muxnote_t dmn;
648: 		eventfd_t value;
649: 
650: 		if (ev[i].events & EPOLLFREE) {
651: 			DISPATCH_CLIENT_CRASH(0, "Do not close random Unix descriptors");
652: 		}
653: 
654: 		switch (ev[i].data.u32) {
655: 		case DISPATCH_EPOLL_EVENTFD:
656: 			dispatch_assume_zero(eventfd_read(_dispatch_eventfd, &value));
657: 			break;
658: 
659: 		case DISPATCH_EPOLL_CLOCK_WALL:
660: 			_dispatch_event_merge_timer(DISPATCH_CLOCK_WALL);
661: 			break;
662: 
663: 		case DISPATCH_EPOLL_CLOCK_UPTIME:
664: 			_dispatch_event_merge_timer(DISPATCH_CLOCK_UPTIME);
665: 			break;
666: 
667: 		case DISPATCH_EPOLL_CLOCK_MONOTONIC:
668: 			_dispatch_event_merge_timer(DISPATCH_CLOCK_MONOTONIC);
669: 			break;
670: 
671: 		default:
672: 			dmn = ev[i].data.ptr;
673: 			switch (dmn->dmn_filter) {
674: 			case EVFILT_SIGNAL:
675: 				_dispatch_event_merge_signal(dmn);
676: 				break;
677: 
678: 			case EVFILT_READ:
679: 				_dispatch_event_merge_fd(dmn, ev[i].events);
680: 				break;
681: 			}
682: 		}
683: 	}
684: }
