371: DISPATCH_NOINLINE
372: static void
373: _dispatch_kevent_print_error(dispatch_kevent_t ke)
374: {
375: 	dispatch_unote_class_t du = NULL;
376: 	_dispatch_debug("kevent[0x%llx]: handling error",
377: 			(unsigned long long)ke->udata);
378: 	if (ke->flags & EV_DELETE) {
379: 		if (ke->flags & EV_UDATA_SPECIFIC) {
380: 			if (ke->data == EINPROGRESS) {
381: 				// deferred EV_DELETE
382: 				return;
383: 			}
384: 		}
385: 		// for EV_DELETE if the update was deferred we may have reclaimed
386: 		// the udata already, and it is unsafe to dereference it now.
387: 	} else if (_dispatch_kevent_unote_is_muxed(ke)) {
388: 		ke->flags |= _dispatch_kevent_get_muxnote(ke)->dmn_kev.flags;
389: 	} else if (ke->udata) {
390: 		du = (dispatch_unote_class_t)(uintptr_t)ke->udata;
391: 		if (!_dispatch_unote_registered(du)) {
392: 			ke->flags |= EV_ADD;
393: 		}
394: 	}
395: 
396: 	switch (ke->data) {
397: 	case 0:
398: 		return;
399: #if DISPATCH_USE_KEVENT_QOS
400: 	case ERANGE: /* A broken QoS was passed to kevent_id() */
401: 		DISPATCH_INTERNAL_CRASH(ke->qos, "Invalid kevent priority");
402: #endif
403: 	default:
404: 		// log the unexpected error
405: 		_dispatch_bug_kevent_client("kevent", _evfiltstr(ke->filter),
406: 				!ke->udata ? NULL :
407: 				ke->flags & EV_DELETE ? "delete" :
408: 				ke->flags & EV_ADD ? "add" :
409: 				ke->flags & EV_ENABLE ? "enable" : "monitor",
410: 				(int)ke->data, ke->ident, (uint64_t)ke->udata, du);
411: 	}
412: }
