414: DISPATCH_ALWAYS_INLINE
415: static inline void
416: _dispatch_kevent_merge_ev_flags(dispatch_unote_t du, uint32_t flags)
417: {
418: 	if (unlikely(!(flags & EV_UDATA_SPECIFIC) && (flags & EV_ONESHOT))) {
419: 		_dispatch_unote_unregister(du, DUU_DELETE_ACK | DUU_MUST_SUCCEED);
420: 		return;
421: 	}
422: 
423: 	if (flags & EV_DELETE) {
424: 		// When a speculative deletion is requested by libdispatch,
425: 		// and the kernel is about to deliver an event, it can acknowledge
426: 		// our wish by delivering the event as a (EV_DELETE | EV_ONESHOT)
427: 		// event and dropping the knote at once.
428: 		_dispatch_unote_state_set(du, DU_STATE_NEEDS_DELETE);
429: 	} else if (flags & (EV_ONESHOT | EV_VANISHED)) {
430: 		// EV_VANISHED events if re-enabled will produce another EV_VANISHED
431: 		// event. To avoid an infinite loop of such events, mark the unote
432: 		// as needing deletion so that _dispatch_unote_needs_rearm()
433: 		// eventually returns false.
434: 		//
435: 		// mach channels crash on EV_VANISHED, and dispatch sources stay
436: 		// in a limbo until canceled (explicitly or not).
437: 		dispatch_unote_state_t du_state = _dispatch_unote_state(du);
438: 		du_state |= DU_STATE_NEEDS_DELETE;
439: 		du_state &= ~DU_STATE_ARMED;
440: 		_dispatch_unote_state_set(du, du_state);
441: 	} else if (likely(flags & EV_DISPATCH)) {
442: 		_dispatch_unote_state_clear_bit(du, DU_STATE_ARMED);
443: 	} else {
444: 		return;
445: 	}
446: 
447: 	_dispatch_du_debug((flags & EV_VANISHED) ? "vanished" :
448: 			(flags & EV_DELETE) ? "deleted oneshot" :
449: 			(flags & EV_ONESHOT) ? "oneshot" : "disarmed", du._du);
450: }
