452: DISPATCH_NOINLINE
453: static void
454: _dispatch_kevent_merge(dispatch_unote_t du, dispatch_kevent_t ke)
455: {
456: 	dispatch_unote_action_t action = dux_type(du._du)->dst_action;
457: 	pthread_priority_t pp = 0;
458: 	uintptr_t data;
459: 
460: 	// once we modify the queue atomic flags below, it will allow concurrent
461: 	// threads running _dispatch_source_invoke2 to dispose of the source,
462: 	// so we can't safely borrow the reference we get from the muxnote udata
463: 	// anymore, and need our own <rdar://20382435>
464: 	_dispatch_retain_unote_owner(du);
465: 
466: 	switch (action) {
467: 	case DISPATCH_UNOTE_ACTION_PASS_DATA:
468: 		data = (uintptr_t)ke->data;
469: 		break;
470: 
471: 	case DISPATCH_UNOTE_ACTION_PASS_FFLAGS:
472: 		data = (uintptr_t)ke->fflags;
473: #if HAVE_MACH
474: 		if (du._du->du_filter == EVFILT_MACHPORT) {
475: 			data = DISPATCH_MACH_RECV_MESSAGE;
476: 		}
477: #endif
478: 		break;
479: 
480: 	case DISPATCH_UNOTE_ACTION_SOURCE_SET_DATA:
481: 		// ke->data is signed and "negative available data" makes no sense
482: 		// zero bytes happens when EV_EOF is set
483: 		dispatch_assert(ke->data >= 0l);
484: 		data = (unsigned long)ke->data;
485: 		os_atomic_store2o(du._dr, ds_pending_data, ~data, relaxed);
486: 		break;
487: 
488: 	case DISPATCH_UNOTE_ACTION_SOURCE_ADD_DATA:
489: 		data = (unsigned long)ke->data;
490: 		if (data) os_atomic_add2o(du._dr, ds_pending_data, data, relaxed);
491: 		break;
492: 
493: 	case DISPATCH_UNOTE_ACTION_SOURCE_OR_FFLAGS:
494: 		data = ke->fflags & du._du->du_fflags;
495: 		if (du._dr->du_has_extended_status) {
496: 			uint64_t odata, ndata, value;
497: 			uint32_t status = (uint32_t)ke->data;
498: 
499: 			// We combine the data and status into a single 64-bit value.
500: 			value = DISPATCH_SOURCE_COMBINE_DATA_AND_STATUS(data, status);
501: 			os_atomic_rmw_loop2o(du._dr, ds_pending_data, odata, ndata, relaxed, {
502: 				ndata = DISPATCH_SOURCE_GET_DATA(odata) | value;
503: 			});
504: #if HAVE_MACH
505: 		} else if (du._du->du_filter == EVFILT_MACHPORT) {
506: 			data = DISPATCH_MACH_RECV_MESSAGE;
507: 			os_atomic_store2o(du._dr, ds_pending_data, data, relaxed);
508: #endif
509: 		} else {
510: 			if (data) os_atomic_or2o(du._dr, ds_pending_data, data, relaxed);
511: 		}
512: 		break;
513: 
514: 	default:
515: 		DISPATCH_INTERNAL_CRASH(action, "Corrupt unote action");
516: 	}
517: 
518: 	_dispatch_kevent_merge_ev_flags(du, ke->flags);
519: #if DISPATCH_USE_KEVENT_QOS
520: 	pp = ((pthread_priority_t)ke->qos) & ~_PTHREAD_PRIORITY_FLAGS_MASK;
521: #endif
522: 	return dux_merge_evt(du._du, ke->flags, data, pp);
523: }
