525: DISPATCH_NOINLINE
526: static void
527: _dispatch_kevent_merge_muxed(dispatch_kevent_t ke)
528: {
529: 	dispatch_muxnote_t dmn = _dispatch_kevent_get_muxnote(ke);
530: 	dispatch_unote_linkage_t dul, dul_next;
531: 
532: 	if (ke->flags & (EV_ONESHOT | EV_DELETE)) {
533: 		// tell _dispatch_unote_unregister_muxed() the kernel half is gone
534: 		dmn->dmn_kev.flags |= EV_DELETE;
535: 	}
536: 	LIST_FOREACH_SAFE(dul, &dmn->dmn_unotes_head, du_link, dul_next) {
537: 		_dispatch_kevent_merge(_dispatch_unote_linkage_get_unote(dul), ke);
538: 	}
539: }
540: 
541: /*
542:  * If the kevent implementation doesn't support EVFILT_USER for
543:  * signaling, then we use EVFILT_TIMER with EV_ONESHOT with this ident
544:  * to make do.
545:  */
546: #define DISPATCH_KEVENT_ERSATZ_EVFILT_USER_IDENT (~0ull << 9)
547: 
548: DISPATCH_NOINLINE
549: static void
550: _dispatch_kevent_drain(dispatch_kevent_t ke)
551: {
552: #ifdef EVFILT_USER
553: 	if (ke->filter == EVFILT_USER) {
554: #else
555: 	if (ke->filter == EVFILT_TIMER && ke->ident == DISPATCH_KEVENT_ERSATZ_EVFILT_USER_IDENT) {
556: #endif
557: 		_dispatch_kevent_mgr_debug("received", ke);
558: 		return;
559: 	}
560: #if DISPATCH_USE_KEVENT_WORKLOOP
561: 	if (ke->filter == EVFILT_WORKLOOP) {
562: 		return _dispatch_kevent_workloop_poke_drain(ke);
563: 	}
564: #endif // DISPATCH_USE_KEVENT_WORKLOOP
565: 	_dispatch_kevent_debug("received", ke);
566: 	if (unlikely(ke->flags & EV_ERROR)) {
567: 		if (ke->filter == EVFILT_PROC && ke->data == ESRCH) {
568: 			// <rdar://problem/5067725&6626350> EVFILT_PROC may fail with ESRCH
569: 			// when the process exists but is a zombie. As a workaround, we
570: 			// simulate an exit event for any EVFILT_PROC with an invalid pid.
571: 			ke->flags  = EV_UDATA_SPECIFIC | EV_ONESHOT | EV_DELETE;
572: 			ke->fflags = NOTE_EXIT;
573: 			ke->data   = 0;
574: 			_dispatch_kevent_debug("synthetic NOTE_EXIT", ke);
575: 		} else {
576: 			return _dispatch_kevent_print_error(ke);
577: 		}
578: 	}
579: 	if (ke->filter == EVFILT_TIMER) {
580: 		return _dispatch_kevent_timer_drain(ke);
581: 	}
582: 
583: #if HAVE_MACH
584: 	if (ke->filter == EVFILT_MACHPORT && _dispatch_kevent_mach_msg_size(ke)) {
585: 		return _dispatch_kevent_mach_msg_drain(ke);
586: 	}
587: #endif
588: 
589: 	if (_dispatch_kevent_unote_is_muxed(ke)) {
590: 		return _dispatch_kevent_merge_muxed(ke);
591: 	}
592: 	return _dispatch_kevent_merge(_dispatch_kevent_get_unote(ke), ke);
593: }
