598: DISPATCH_NOINLINE
599: static void
600: _dispatch_kq_create(intptr_t *fd_ptr)
601: {
602: 	static const dispatch_kevent_s kev = {
603: #ifdef EVFILT_USER
604: 		.ident = 1,
605: 		.filter = EVFILT_USER,
606: 		.flags = EV_ADD|EV_CLEAR,
607: 		.udata = (dispatch_kevent_udata_t)DISPATCH_WLH_MANAGER,
608: #else
609: 		.ident = DISPATCH_KEVENT_ERSATZ_EVFILT_USER_IDENT,
610: 		.filter = EVFILT_TIMER,
611: 		.flags = EV_ADD|EV_DISABLE|EV_ONESHOT,
612: 		.data = 1,
613: #endif
614: 	};
615: 	int kqfd;
616: 
617: 	_dispatch_fork_becomes_unsafe();
618: #if DISPATCH_USE_GUARDED_FD
619: 	guardid_t guard = (uintptr_t)fd_ptr;
620: 	kqfd = guarded_kqueue_np(&guard, GUARD_CLOSE | GUARD_DUP);
621: #else
622: 	kqfd = kqueue();
623: #endif
624: 	if (kqfd == -1) {
625: 		int err = errno;
626: 		switch (err) {
627: 		case EMFILE:
628: 			DISPATCH_CLIENT_CRASH(err, "kqueue() failure: "
629: 					"process is out of file descriptors");
630: 			break;
631: 		case ENFILE:
632: 			DISPATCH_CLIENT_CRASH(err, "kqueue() failure: "
633: 					"system is out of file descriptors");
634: 			break;
635: 		case ENOMEM:
636: 			DISPATCH_CLIENT_CRASH(err, "kqueue() failure: "
637: 					"kernel is out of memory");
638: 			break;
639: 		default:
640: 			DISPATCH_INTERNAL_CRASH(err, "kqueue() failure");
641: 			break;
642: 		}
643: 	}
644: #if DISPATCH_USE_KEVENT_QOS
645: 	dispatch_assume_zero(kevent_qos(kqfd, &kev, 1, NULL, 0, NULL, NULL, 0));
646: #else
647: 	dispatch_assume_zero(kevent(kqfd, &kev, 1, NULL, 0, NULL));
648: #endif
649: 	*fd_ptr = kqfd;
650: }
651: #endif
