659: static void
660: _dispatch_kq_init(void *context)
661: {
662: 	bool *kq_initialized = context;
663: 
664: 	_dispatch_fork_becomes_unsafe();
665: 	if (unlikely(getenv("LIBDISPATCH_TIMERS_FORCE_MAX_LEEWAY"))) {
666: 		_dispatch_timers_force_max_leeway = true;
667: 	}
668: 	*kq_initialized = true;
669: 
670: #if DISPATCH_USE_KEVENT_WORKQUEUE
671: 	_dispatch_kevent_workqueue_init();
672: 	if (_dispatch_kevent_workqueue_enabled) {
673: 		int r;
674: 		int kqfd = _dispatch_kq_fd();
675: 		const dispatch_kevent_s ke = {
676: 			.ident = 1,
677: 			.filter = EVFILT_USER,
678: 			.flags = EV_ADD|EV_CLEAR,
679: 			.qos = _PTHREAD_PRIORITY_EVENT_MANAGER_FLAG,
680: 			.udata = (dispatch_kevent_udata_t)DISPATCH_WLH_MANAGER,
681: 		};
682: retry:
683: 		r = kevent_qos(kqfd, &ke, 1, NULL, 0, NULL, NULL,
684: 				KEVENT_FLAG_WORKQ|KEVENT_FLAG_IMMEDIATE);
685: 		if (unlikely(r == -1)) {
686: 			int err = errno;
687: 			switch (err) {
688: 			case EINTR:
689: 				goto retry;
690: 			default:
691: 				DISPATCH_CLIENT_CRASH(err,
692: 						"Failed to initalize workqueue kevent");
693: 				break;
694: 			}
695: 		}
696: 		return;
697: 	}
698: #endif // DISPATCH_USE_KEVENT_WORKQUEUE
699: #if DISPATCH_USE_MGR_THREAD
700: 	_dispatch_kq_create((intptr_t *)&_dispatch_mgr_q.do_ctxt);
701: 	_dispatch_trace_item_push(_dispatch_mgr_q.do_targetq, &_dispatch_mgr_q);
702: 	dx_push(_dispatch_mgr_q.do_targetq, &_dispatch_mgr_q, 0);
703: #endif // DISPATCH_USE_MGR_THREAD
704: }
