712: DISPATCH_NOINLINE
713: static int
714: _dispatch_kq_poll(dispatch_wlh_t wlh, dispatch_kevent_t ke, int n,
715: 		dispatch_kevent_t ke_out, int n_out, void *buf, size_t *avail,
716: 		uint32_t flags)
717: {
718: 	bool kq_initialized = false;
719: 	int r = 0;
720: 
721: 	dispatch_once_f(&_dispatch_kq_poll_pred, &kq_initialized, _dispatch_kq_init);
722: 	if (unlikely(kq_initialized)) {
723: 		// The calling thread was the one doing the initialization
724: 		//
725: 		// The event loop needs the memory pressure source and debug channel,
726: 		// however creating these will recursively call _dispatch_kq_poll(),
727: 		// so we can't quite initialize them under the dispatch once.
728: 		_dispatch_memorypressure_init();
729: 		_voucher_activity_debug_channel_init();
730: 	}
731: 
732: #if !DISPATCH_USE_KEVENT_QOS
733: 	if (flags & KEVENT_FLAG_ERROR_EVENTS) {
734: 		// emulate KEVENT_FLAG_ERROR_EVENTS
735: 		for (r = 0; r < n; r++) {
736: 			ke[r].flags |= EV_RECEIPT;
737: 		}
738: 		n_out = n;
739: 	}
740: #endif
741: 
742: retry:
743: 	if (unlikely(wlh == NULL)) {
744: 		DISPATCH_INTERNAL_CRASH(wlh, "Invalid wlh");
745: 	} else if (wlh == DISPATCH_WLH_ANON) {
746: 		int kqfd = _dispatch_kq_fd();
747: #if DISPATCH_USE_KEVENT_QOS
748: 		if (_dispatch_kevent_workqueue_enabled) {
749: 			flags |= KEVENT_FLAG_WORKQ;
750: 		}
751: 		r = kevent_qos(kqfd, ke, n, ke_out, n_out, buf, avail, flags);
752: #else
753: 		(void)buf;
754: 		(void)avail;
755: 		const struct timespec timeout_immediately = {}, *timeout = NULL;
756: 		if (flags & KEVENT_FLAG_IMMEDIATE) timeout = &timeout_immediately;
757: 		r = kevent(kqfd, ke, n, ke_out, n_out, timeout);
758: #endif
759: #if DISPATCH_USE_KEVENT_WORKLOOP
760: 	} else {
761: 		flags |= KEVENT_FLAG_WORKLOOP;
762: 		if (!(flags & KEVENT_FLAG_ERROR_EVENTS)) {
763: 			flags |= KEVENT_FLAG_DYNAMIC_KQ_MUST_EXIST;
764: 		}
765: 		r = kevent_id((uintptr_t)wlh, ke, n, ke_out, n_out, buf, avail, flags);
766: #endif // DISPATCH_USE_KEVENT_WORKLOOP
767: 	}
768: 	if (unlikely(r == -1)) {
769: 		int err = errno;
770: 		switch (err) {
771: 		case ENOMEM:
772: 			_dispatch_temporary_resource_shortage();
773: 			DISPATCH_FALLTHROUGH;
774: 		case EINTR:
775: 			goto retry;
776: 		case EBADF:
777: 			DISPATCH_CLIENT_CRASH(err, "Do not close random Unix descriptors");
778: #if DISPATCH_USE_KEVENT_WORKLOOP
779: 		case ENOENT:
780: 			if ((flags & KEVENT_FLAG_ERROR_EVENTS) &&
781: 					(flags & KEVENT_FLAG_DYNAMIC_KQ_MUST_EXIST)) {
782: 				return 0;
783: 			}
784: 			DISPATCH_FALLTHROUGH;
785: #endif // DISPATCH_USE_KEVENT_WORKLOOP
786: 		default:
787: 			DISPATCH_CLIENT_CRASH(err, "Unexpected error from kevent");
788: 		}
789: 	}
790: 	return r;
791: }
