793: DISPATCH_NOINLINE
794: static int
795: _dispatch_kq_drain(dispatch_wlh_t wlh, dispatch_kevent_t ke, int n,
796: 		uint32_t flags)
797: {
798: 	dispatch_kevent_s ke_out[DISPATCH_DEFERRED_ITEMS_EVENT_COUNT];
799: 	bool poll_for_events = !(flags & KEVENT_FLAG_ERROR_EVENTS);
800: 	int i, n_out = countof(ke_out), r = 0;
801: 	size_t *avail = NULL;
802: 	void *buf = NULL;
803: 
804: #if DISPATCH_USE_KEVENT_QOS
805: 	size_t size;
806: 	if (poll_for_events) {
807: 		size = DISPATCH_MACH_RECEIVE_MAX_INLINE_MESSAGE_SIZE +
808: 				DISPATCH_MACH_TRAILER_SIZE;
809: 		buf = alloca(size);
810: 		avail = &size;
811: 	}
812: #endif
813: 
814: #if DISPATCH_DEBUG
815: 	for (r = 0; r < n; r++) {
816: #ifdef EVFILT_USER
817: 		if (ke[r].filter != EVFILT_USER || DISPATCH_MGR_QUEUE_DEBUG) {
818: 			_dispatch_kevent_debug_n(NULL, ke + r, r, n);
819: 		}
820: #else
821: 		if (DISPATCH_MGR_QUEUE_DEBUG) {
822: 			_dispatch_kevent_debug_n(NULL, ke + r, r, n);
823: 		}
824: #endif
825: 	}
826: #endif
827: 
828: 	if (poll_for_events) _dispatch_clear_return_to_kernel();
829: 	n = _dispatch_kq_poll(wlh, ke, n, ke_out, n_out, buf, avail, flags);
830: 	if (n == 0) {
831: 		r = 0;
832: 	} else if (flags & KEVENT_FLAG_ERROR_EVENTS) {
833: 		for (i = 0, r = 0; i < n; i++) {
834: 			if ((ke_out[i].flags & EV_ERROR) && ke_out[i].data) {
835: 				_dispatch_kevent_drain(&ke_out[i]);
836: 				r = (int)ke_out[i].data;
837: 			}
838: 		}
839: 	} else {
840: #if DISPATCH_USE_KEVENT_WORKLOOP
841: 		if (ke_out[0].flags & EV_ERROR) {
842: 			// When kevent returns errors it doesn't process the kqueue
843: 			// and doesn't rearm the return-to-kernel notification
844: 			// We need to assume we have to go back.
845: 			_dispatch_set_return_to_kernel();
846: 		}
847: #endif // DISPATCH_USE_KEVENT_WORKLOOP
848: 		for (i = 0, r = 0; i < n; i++) {
849: 			_dispatch_kevent_drain(&ke_out[i]);
850: 		}
851: 	}
852: 	return r;
853: }
