898: DISPATCH_ALWAYS_INLINE
899: static inline int
900: _dispatch_kq_deferred_find_slot(dispatch_deferred_items_t ddi,
901: 		int16_t filter, uint64_t ident, dispatch_kevent_udata_t udata)
902: {
903: 	dispatch_kevent_t events = ddi->ddi_eventlist;
904: 	int i;
905: 
906: 	for (i = 0; i < ddi->ddi_nevents; i++) {
907: 		if (events[i].filter == filter && events[i].ident == ident &&
908: 				events[i].udata == udata) {
