915: DISPATCH_ALWAYS_INLINE
916: static inline dispatch_kevent_t
917: _dispatch_kq_deferred_reuse_slot(dispatch_wlh_t wlh,
918: 		dispatch_deferred_items_t ddi, int slot)
919: {
920: 	if (wlh != DISPATCH_WLH_ANON) _dispatch_set_return_to_kernel();
921: 	if (unlikely(slot == ddi->ddi_maxevents)) {
922: 		int nevents = ddi->ddi_nevents;
923: 		ddi->ddi_nevents = 1;
924: 		_dispatch_kq_update_all(wlh, ddi->ddi_eventlist, nevents);
925: 		dispatch_assert(ddi->ddi_nevents == 1);
926: 		slot = 0;
927: 	} else if (slot == ddi->ddi_nevents) {
928: 		ddi->ddi_nevents++;
929: 	}
930: 	return ddi->ddi_eventlist + slot;
931: }
