933: DISPATCH_ALWAYS_INLINE
934: static inline void
935: _dispatch_kq_deferred_discard_slot(dispatch_deferred_items_t ddi, int slot)
936: {
937: 	if (slot < ddi->ddi_nevents) {
938: 		int last = --ddi->ddi_nevents;
939: 		if (slot != last) {
940: 			ddi->ddi_eventlist[slot] = ddi->ddi_eventlist[last];
941: 		}
942: 	}
943: }
