945: DISPATCH_NOINLINE
946: static void
947: _dispatch_kq_deferred_update(dispatch_wlh_t wlh, dispatch_kevent_t ke)
948: {
949: 	dispatch_deferred_items_t ddi = _dispatch_deferred_items_get();
950: 
951: 	if (ddi && ddi->ddi_wlh == wlh && ddi->ddi_maxevents) {
952: 		int slot = _dispatch_kq_deferred_find_slot(ddi, ke->filter, ke->ident,
953: 				ke->udata);
954: 		dispatch_kevent_t dk = _dispatch_kq_deferred_reuse_slot(wlh, ddi, slot);
955: 		*dk = *ke;
956: #ifdef EVFILT_USER
957: 		if (ke->filter != EVFILT_USER) {
958: 			_dispatch_kevent_mgr_debug("deferred", ke);
959: 		}
960: #else
961: 		_dispatch_kevent_mgr_debug("deferred", ke);
962: #endif
963: 	} else {
964: 		_dispatch_kq_update_one(wlh, ke);
965: 	}
966: }
