973: 	if (ddi && ddi->ddi_wlh == wlh) {
974: 		int slot = _dispatch_kq_deferred_find_slot(ddi, ke->filter, ke->ident,
975: 				ke->udata);
976: 		_dispatch_kq_deferred_discard_slot(ddi, slot);
977: 	}
978: 	return _dispatch_kq_update_one(wlh, ke);
