1024: #if DISPATCH_HAVE_DIRECT_KNOTES
1025: DISPATCH_NOINLINE
1026: static bool
1027: _dispatch_kq_unote_update(dispatch_wlh_t wlh, dispatch_unote_t _du,
1028: 		uint16_t action_flags)
1029: {
1030: 	dispatch_deferred_items_t ddi = _dispatch_deferred_items_get();
1031: 	dispatch_unote_class_t du = _du._du;
1032: 	dispatch_kevent_t ke;
1033: 	int r = 0;
1034: 
1035: 	if (action_flags & EV_ADD) {
1036: 		// as soon as we register we may get an event delivery and it has to
1037: 		// see du_state already set, else it will not unregister the kevent
1038: 		_dispatch_wlh_retain(wlh);
1039: 		_dispatch_unote_state_set(du, wlh, DU_STATE_ARMED);
1040: 	}
1041: 
1042: 	if (ddi && ddi->ddi_wlh == wlh) {
1043: 		int slot = _dispatch_kq_deferred_find_slot(ddi,
1044: 				du->du_filter, du->du_ident, (dispatch_kevent_udata_t)du);
1045: 		if (slot < ddi->ddi_nevents) {
1046: 			// <rdar://problem/26202376> when deleting and an enable is pending,
1047: 			// we must merge EV_ENABLE to do an immediate deletion
1048: 			action_flags |= (ddi->ddi_eventlist[slot].flags & EV_ENABLE);
1049: 		}
1050: 
1051: 		if (!(action_flags & EV_ADD) && (action_flags & EV_ENABLE)) {
1052: 			// can be deferred, so do it!
1053: 			ke = _dispatch_kq_deferred_reuse_slot(wlh, ddi, slot);
1054: 			_dispatch_kq_unote_set_kevent(du, ke, action_flags);
1055: 			_dispatch_kevent_debug("deferred", ke);
1056: 			goto done;
1057: 		}
1058: 
1059: 		// get rid of the deferred item if any, we can't wait
1060: 		_dispatch_kq_deferred_discard_slot(ddi, slot);
1061: 	}
1062: 
1063: 	if (action_flags) {
1064: 		dispatch_kevent_s dk;
1065: 		_dispatch_kq_unote_set_kevent(du, &dk, action_flags);
1066: 		r = _dispatch_kq_update_one(wlh, &dk);
1067: 	}
1068: 
1069: done:
1070: 	if (action_flags & EV_ADD) {
1071: 		if (unlikely(r)) {
1072: 			_dispatch_wlh_release(wlh);
1073: 			_dispatch_unote_state_set(du, DU_STATE_UNREGISTERED);
1074: 		} else {
1075: 			_dispatch_du_debug("installed", du);
1076: 		}
1077: 		return r == 0;
1078: 	}
1079: 
1080: 	if (action_flags & EV_DELETE) {
1081: 		if (r == EINPROGRESS) {
1082: 			_dispatch_du_debug("deferred delete", du);
1083: 			return false;
1084: 		}
1085: 		_dispatch_wlh_release(wlh);
1086: 		_dispatch_unote_state_set(du, DU_STATE_UNREGISTERED);
1087: 		_dispatch_du_debug("deleted", du);
1088: 	} else if (action_flags & EV_ENABLE) {
1089: 		_dispatch_du_debug("rearmed", du);
1090: 	}
1091: 
1092: 	dispatch_assume_zero(r);
1093: 	return true;
1094: }
1095: #endif
