1146: bool
1147: _dispatch_unote_register_muxed(dispatch_unote_t du)
1148: {
1149: 	struct dispatch_muxnote_bucket_s *dmb = _dispatch_unote_muxnote_bucket(du);
1150: 	dispatch_muxnote_t dmn;
1151: 	bool installed = true;
1152: 
1153: 	dmn = _dispatch_muxnote_find(dmb, du._du->du_ident, du._du->du_filter);
1154: 	if (dmn) {
1155: 		uint32_t flags = du._du->du_fflags & ~dmn->dmn_kev.fflags;
1156: 		if (flags) {
1157: 			dmn->dmn_kev.fflags |= flags;
1158: 			if (unlikely(dux_type(du._du)->dst_update_mux)) {
1159: 				installed = dux_type(du._du)->dst_update_mux(dmn);
1160: 			} else {
1161: 				installed = !_dispatch_kq_immediate_update(DISPATCH_WLH_ANON,
1162: 						&dmn->dmn_kev);
1163: 			}
1164: 			if (!installed) dmn->dmn_kev.fflags &= ~flags;
1165: 		}
1166: 	} else {
1167: 		dmn = _dispatch_calloc(1, sizeof(struct dispatch_muxnote_s));
1168: 		_dispatch_kq_unote_set_kevent(du, &dmn->dmn_kev, EV_ADD | EV_ENABLE);
1169: #if DISPATCH_USE_KEVENT_QOS
1170: 		dmn->dmn_kev.qos = _PTHREAD_PRIORITY_EVENT_MANAGER_FLAG;
1171: #endif
1172: 		dmn->dmn_kev.udata = (dispatch_kevent_udata_t)((uintptr_t)dmn |
1173: 				DISPATCH_KEVENT_MUXED_MARKER);
1174: 		if (unlikely(dux_type(du._du)->dst_update_mux)) {
1175: 			installed = dux_type(du._du)->dst_update_mux(dmn);
1176: 		} else {
1177: 			installed = !_dispatch_kq_immediate_update(DISPATCH_WLH_ANON,
1178: 					&dmn->dmn_kev);
1179: 		}
1180: 		if (installed) {
1181: 			dmn->dmn_kev.flags &= ~(EV_ADD | EV_VANISHED);
1182: 			LIST_INSERT_HEAD(dmb, dmn, dmn_list);
1183: 		} else {
1184: 			free(dmn);
1185: 		}
1186: 	}
1187: 
1188: 	if (installed) {
1189: 		dispatch_unote_linkage_t dul = _dispatch_unote_get_linkage(du);
1190: 		LIST_INSERT_HEAD(&dmn->dmn_unotes_head, dul, du_link);
1191: #if HAVE_MACH
1192: 		if (du._du->du_filter == DISPATCH_EVFILT_MACH_NOTIFICATION) {
1193: 			os_atomic_store2o(du._dmsr, dmsr_notification_armed,
1194: 					DISPATCH_MACH_NOTIFICATION_ARMED(dmn), relaxed);
1195: 		}
1196: #endif
1197: 		dul->du_muxnote = dmn;
1198: 		_dispatch_unote_state_set(du, DISPATCH_WLH_ANON, DU_STATE_ARMED);
1199: 		_dispatch_du_debug("installed", du._du);
1200: 	}
1201: 	return installed;
1202: }
