1205: _dispatch_unote_resume_muxed(dispatch_unote_t du)
1206: {
1207: 	_dispatch_unote_state_set_bit(du, DU_STATE_ARMED);
1208: 	if (unlikely(dux_type(du._du)->dst_update_mux)) {
1209: 		dispatch_unote_linkage_t dul = _dispatch_unote_get_linkage(du);
1210: 		dux_type(du._du)->dst_update_mux(dul->du_muxnote);
1211: 	} else {
1212: 		dispatch_unote_linkage_t dul = _dispatch_unote_get_linkage(du);
1213: 		dispatch_muxnote_t dmn = dul->du_muxnote;
