1218: bool
1219: _dispatch_unote_unregister_muxed(dispatch_unote_t du)
1220: {
1221: 	dispatch_unote_linkage_t dul = _dispatch_unote_get_linkage(du);
1222: 	dispatch_muxnote_t dmn = dul->du_muxnote;
1223: 	bool update = false, dispose = false;
1224: 
1225: #if HAVE_MACH
1226: 	if (dmn->dmn_kev.filter == DISPATCH_EVFILT_MACH_NOTIFICATION) {
1227: 		os_atomic_store2o(du._dmsr, dmsr_notification_armed, false, relaxed);
1228: 	}
1229: #endif
1230: 	_dispatch_unote_state_set(du, DU_STATE_UNREGISTERED);
1231: 	LIST_REMOVE(dul, du_link);
1232: 	_LIST_TRASH_ENTRY(dul, du_link);
1233: 	dul->du_muxnote = NULL;
1234: 
1235: 	if (LIST_EMPTY(&dmn->dmn_unotes_head)) {
1236: 		dispose = true;
1237: 		update = !(dmn->dmn_kev.flags & EV_DELETE);
1238: 		dmn->dmn_kev.flags |= EV_DELETE;
1239: 	} else {
1240: 		uint32_t fflags = dux_type(du._du)->dst_fflags;
1241: 		LIST_FOREACH(dul, &dmn->dmn_unotes_head, du_link) {
1242: 			du = _dispatch_unote_linkage_get_unote(dul);
1243: 			fflags |= du._du->du_fflags;
1244: 		}
1245: 		if (dmn->dmn_kev.fflags & ~fflags) {
1246: 			dmn->dmn_kev.fflags &= fflags;
1247: 			update = true;
1248: 		}
1249: 	}
1250: 	if (update) {
1251: 		if (unlikely(dux_type(du._du)->dst_update_mux)) {
1252: 			dispatch_assume(dux_type(du._du)->dst_update_mux(dmn));
1253: 		} else {
1254: 			_dispatch_kq_deferred_update(DISPATCH_WLH_ANON, &dmn->dmn_kev);
1255: 		}
1256: 	}
1257: 	if (dispose) {
1258: 		LIST_REMOVE(dmn, dmn_list);
1259: 		free(dmn);
1260: 	}
1261: 	_dispatch_du_debug("deleted", du._du);
1262: 	return true;
1263: }
