1279: bool
1280: _dispatch_unote_unregister_direct(dispatch_unote_t du, uint32_t flags)
1281: {
1282: 	dispatch_unote_state_t du_state = _dispatch_unote_state(du);
1283: 	dispatch_wlh_t du_wlh = _du_state_wlh(du_state);
1284: 	dispatch_deferred_items_t ddi = _dispatch_deferred_items_get();
1285: 	uint16_t action = EV_DELETE;
1286: 	if (likely(du_wlh != DISPATCH_WLH_ANON && ddi && ddi->ddi_wlh == du_wlh)) {
1287: #if DISPATCH_USE_KEVENT_WORKLOOP
1288: 		// Workloops are special: event delivery and servicing a workloop
1289: 		// cannot race because the kernel can reason about these.
1290: 		// Unregistering from a workloop is always safe and should always
1291: 		// succeed immediately.
1292: #endif
1293: 		action |= EV_ENABLE;
1294: 		flags |= DUU_DELETE_ACK | DUU_MUST_SUCCEED;
1295: 	}
1296: 
1297: 	if (!_du_state_needs_delete(du_state) || (flags & DUU_DELETE_ACK)) {
1298: 		if (du_state == DU_STATE_NEEDS_DELETE) {
1299: 			// There is no knote to unregister anymore, just do it.
1300: 			_dispatch_unote_state_set(du, DU_STATE_UNREGISTERED);
1301: 			_dispatch_du_debug("acknowledged deleted oneshot", du._du);
1302: 			return true;
1303: 		}
1304: 		if (!_du_state_armed(du_state)) {
1305: 			action |= EV_ENABLE;
1306: 			flags |= DUU_MUST_SUCCEED;
1307: 		}
1308: 		if ((action & EV_ENABLE) || (flags & DUU_PROBE)) {
1309: 			if (_dispatch_kq_unote_update(du_wlh, du, action)) {
1310: 				return true;
1311: 			}
1312: 		}
1313: 	}
1314: 	if (flags & DUU_MUST_SUCCEED) {
1315: 		DISPATCH_INTERNAL_CRASH(0, "Unregistration failed");
1316: 	}
1317: 	return false;
1318: }
1319: #endif // DISPATCH_HAVE_DIRECT_KNOTES
