1385: static bool
1386: _dispatch_kevent_workloop_get_info(dispatch_wlh_t wlh, dispatch_kevent_t ke)
1387: {
1388: 	uint32_t kev_flags = KEVENT_FLAG_IMMEDIATE | KEVENT_FLAG_ERROR_EVENTS |
1389: 			KEVENT_FLAG_DYNAMIC_KQ_MUST_EXIST;
1390: 	*ke = (dispatch_kevent_s){
1391: 		.filter = EVFILT_WORKLOOP,
1392: 		.flags  = EV_ADD | EV_ENABLE,
1393: 	};
1394: 	if (_dispatch_kq_poll(wlh, ke, 1, ke, 1, NULL, NULL, kev_flags)) {
1395: 		dispatch_assert(ke->flags & EV_ERROR);
1396: 		return ke->data == EBUSY;
1397: 	}
1398: 	*ke = (dispatch_kevent_s){
1399: 		.flags = EV_ERROR,
