1406: DISPATCH_ALWAYS_INLINE
1407: static inline pthread_priority_t
1408: _dispatch_kevent_workloop_priority(dispatch_queue_t dq, int which,
1409: 		dispatch_qos_t qos)
1410: {
1411: 	dispatch_priority_t rq_pri = dq->do_targetq->dq_priority;
1412: 	if (qos < _dispatch_priority_qos(rq_pri)) {
1413: 		qos = _dispatch_priority_qos(rq_pri);
1414: 	}
1415: 	if (qos == DISPATCH_QOS_UNSPECIFIED) {
1416: #if 0 // we need to understand why this is happening first...
1417: 		if (which != DISPATCH_WORKLOOP_ASYNC_FROM_SYNC) {
1418: 			DISPATCH_INTERNAL_CRASH(which, "Should have had a QoS");
1419: 		}
1420: #else
1421: 		(void)which;
1422: #endif
1423: 		//
1424: 		// <rdar://32326125> When an enqueue happens right when a barrier ends,
1425: 		// the barrier that ends may notice the next item before the enqueuer
1426: 		// has had the time to set the max QoS on the queue.
1427: 		//
1428: 		// It is inconvenient to drop this thread request, and this case is rare
1429: 		// enough that we instead ask for MAINTENANCE to avoid the kernel
1430: 		// failing with ERANGE.
1431: 		//
1432: 		qos = DISPATCH_QOS_MAINTENANCE;
1433: 	}
1434: 	pthread_priority_t pp = _dispatch_qos_to_pp(qos);
1435: 	return pp | (rq_pri & DISPATCH_PRIORITY_FLAG_OVERCOMMIT);
1436: }
1437: 
1438: DISPATCH_ALWAYS_INLINE_NDEBUG
1439: static void
1440: _dispatch_kq_fill_workloop_event(dispatch_kevent_t ke, int which,
1441: 		dispatch_wlh_t wlh, uint64_t dq_state)
1442: {
1443: 	dispatch_queue_t dq = (dispatch_queue_t)wlh;
1444: 	dispatch_qos_t qos = _dq_state_max_qos(dq_state);
1445: 	pthread_priority_t pp = 0;
1446: 	uint32_t fflags = 0;
1447: 	uint64_t mask = 0;
1448: 	uint16_t action = 0;
1449: 
1450: 	switch (which) {
1451: 	case DISPATCH_WORKLOOP_ASYNC_FROM_SYNC:
1452: 		fflags |= NOTE_WL_END_OWNERSHIP;
1453: 		DISPATCH_FALLTHROUGH;
1454: 	case DISPATCH_WORKLOOP_ASYNC:
1455: 	case DISPATCH_WORKLOOP_ASYNC_DISCOVER_SYNC:
1456: 	case DISPATCH_WORKLOOP_ASYNC_QOS_UPDATE:
1457: 		dispatch_assert(_dq_state_is_base_wlh(dq_state));
1458: 		dispatch_assert(_dq_state_is_enqueued_on_target(dq_state));
1459: 		action = EV_ADD | EV_ENABLE;
1460: 		mask |= DISPATCH_QUEUE_ROLE_MASK;
1461: 		mask |= DISPATCH_QUEUE_ENQUEUED;
1462: 		mask |= DISPATCH_QUEUE_MAX_QOS_MASK;
1463: 		if (which == DISPATCH_WORKLOOP_ASYNC_DISCOVER_SYNC) {
1464: 			dispatch_assert(!_dq_state_in_sync_transfer(dq_state));
1465: 			dispatch_assert(_dq_state_drain_locked(dq_state));
1466: 			mask |= DISPATCH_QUEUE_SYNC_TRANSFER;
1467: 			fflags |= NOTE_WL_DISCOVER_OWNER;
1468: 		} else {
1469: 			fflags |= NOTE_WL_IGNORE_ESTALE;
1470: 		}
1471: 		fflags |= NOTE_WL_UPDATE_QOS;
1472: 		pp = _dispatch_kevent_workloop_priority(dq, which, qos);
1473: 		break;
1474: 
1475: 	case DISPATCH_WORKLOOP_ASYNC_LEAVE_FROM_SYNC:
1476: 		fflags |= NOTE_WL_END_OWNERSHIP;
1477: 		DISPATCH_FALLTHROUGH;
1478: 	case DISPATCH_WORKLOOP_ASYNC_LEAVE_FROM_TRANSFER:
1479: 		fflags |= NOTE_WL_IGNORE_ESTALE;
1480: 		DISPATCH_FALLTHROUGH;
1481: 	case DISPATCH_WORKLOOP_ASYNC_LEAVE:
1482: 		dispatch_assert(!_dq_state_is_enqueued_on_target(dq_state));
1483: 		action = EV_ADD | EV_DELETE | EV_ENABLE;
1484: 		mask |= DISPATCH_QUEUE_ENQUEUED;
1485: 		break;
1486: 
1487: 	case DISPATCH_WORKLOOP_ASYNC_FORCE_END_OWNERSHIP:
1488: 		// 0 is never a valid queue state, so the knote attach will fail due to
1489: 		// the debounce. However, NOTE_WL_END_OWNERSHIP is always observed even
1490: 		// when ESTALE is returned, which is the side effect we're after here.
1491: 		fflags |= NOTE_WL_END_OWNERSHIP;
1492: 		fflags |= NOTE_WL_IGNORE_ESTALE;
1493: 		action = EV_ADD | EV_ENABLE;
1494: 		mask = ~0ull;
1495: 		dq_state = 0;
1496: 		pp = _dispatch_kevent_workloop_priority(dq, which, qos);
1497: 		break;
1498: 
1499: 	case DISPATCH_WORKLOOP_RETARGET:
1500: 		action = EV_ADD | EV_DELETE | EV_ENABLE;
1501: 		fflags |= NOTE_WL_END_OWNERSHIP;
1502: 		break;
1503: 
1504: 	default:
1505: 		DISPATCH_INTERNAL_CRASH(which, "Invalid transition");
1506: 	}
1507: 
1508: 	*ke = (dispatch_kevent_s){
1509: 		.ident  = (uintptr_t)wlh,
1510: 		.filter = EVFILT_WORKLOOP,
1511: 		.flags  = action,
1512: 		.fflags = fflags | NOTE_WL_THREAD_REQUEST,
1513: 		.qos    = (__typeof__(ke->qos))pp,
1514: 		.udata  = (uintptr_t)wlh,
1515: 
1516: 		.ext[EV_EXTIDX_WL_ADDR]  = (uintptr_t)&dq->dq_state,
1517: 		.ext[EV_EXTIDX_WL_MASK]  = mask,
1518: 		.ext[EV_EXTIDX_WL_VALUE] = dq_state,
1519: 	};
1520: 	_dispatch_kevent_wlh_debug(_dispatch_workloop_actions[which], ke);
