109: static dispatch_muxnote_t
110: _dispatch_muxnote_create(dispatch_unote_t du,
111: 		enum _dispatch_muxnote_events events)
112: {
113: 	dispatch_muxnote_t dmn;
114: 	int8_t filter = du._du->du_filter;
115: 	HANDLE handle = (HANDLE)du._du->du_ident;
116: 
117: 	dmn = _dispatch_calloc(1, sizeof(*dmn));
118: 	if (dmn == NULL) {
119: 		DISPATCH_INTERNAL_CRASH(0, "_dispatch_calloc");
120: 	}
121: 	os_atomic_store(&dmn->dmn_refcount, 1, relaxed);
122: 	dmn->dmn_ident = (dispatch_unote_ident_t)handle;
123: 	dmn->dmn_filter = filter;
124: 	dmn->dmn_events = events;
125: 	LIST_INIT(&dmn->dmn_readers_head);
126: 	LIST_INIT(&dmn->dmn_writers_head);
