128: 	switch (filter) {
129: 	case EVFILT_SIGNAL:
130: 		WIN_PORT_ERROR();
131: 		free(dmn);
132: 		return NULL;
133: 
134: 	case EVFILT_WRITE:
135: 	case EVFILT_READ:
136: 		switch (GetFileType(handle)) {
137: 		case FILE_TYPE_UNKNOWN:
138: 			// ensure that an invalid handle was not passed
139: 			(void)dispatch_assume(GetLastError() == NO_ERROR);
140: 			DISPATCH_INTERNAL_CRASH(0, "unknown handle type");
141: 
142: 		case FILE_TYPE_REMOTE:
143: 			DISPATCH_INTERNAL_CRASH(0, "unused handle type");
144: 
145: 		case FILE_TYPE_CHAR:
146: 			// The specified file is a character file, typically a
147: 			// LPT device or a console.
148: 			WIN_PORT_ERROR();
149: 			free(dmn);
150: 			return NULL;
151: 
152: 		case FILE_TYPE_DISK:
153: 			// The specified file is a disk file
154: 			dmn->dmn_handle_type = DISPATCH_MUXNOTE_HANDLE_TYPE_FILE;
155: 			break;
156: 
157: 		case FILE_TYPE_PIPE:
158: 			// The specified file is a socket, a named pipe, or an
159: 			// anonymous pipe.
160: 			dmn->dmn_handle_type = _dispatch_handle_is_socket(handle)
161: 					? DISPATCH_MUXNOTE_HANDLE_TYPE_SOCKET
162: 					: DISPATCH_MUXNOTE_HANDLE_TYPE_PIPE;
163: 			break;
164: 		}
165: 
166: 		break;
167: 
168: 	default:
169: 		DISPATCH_INTERNAL_CRASH(0, "unexpected filter");
170: 	}
