176: static void
177: _dispatch_muxnote_disarm_events(dispatch_muxnote_t dmn,
178: 		enum _dispatch_muxnote_events events)
179: {
180: 	long lNetworkEvents;
181: 	dmn->dmn_events &= ~events;
182: 	switch (dmn->dmn_handle_type) {
183: 	case DISPATCH_MUXNOTE_HANDLE_TYPE_INVALID:
184: 		DISPATCH_INTERNAL_CRASH(0, "invalid handle");
185: 
186: 	case DISPATCH_MUXNOTE_HANDLE_TYPE_FILE:
187: 		break;
188: 
189: 	case DISPATCH_MUXNOTE_HANDLE_TYPE_PIPE:
190: 		if ((events & DISPATCH_MUXNOTE_EVENT_READ) && dmn->dmn_thread) {
191: 			// Keep trying to cancel ReadFile() until the thread exits
192: 			os_atomic_store(&dmn->dmn_stop, true, relaxed);
193: 			SetEvent(dmn->dmn_event);
194: 			do {
195: 				CancelIoEx((HANDLE)dmn->dmn_ident, /* lpOverlapped */ NULL);
196: 			} while (WaitForSingleObject(dmn->dmn_thread, 1) == WAIT_TIMEOUT);
197: 			CloseHandle(dmn->dmn_thread);
198: 			dmn->dmn_thread = NULL;
199: 		}
200: 		break;
201: 
202: 	case DISPATCH_MUXNOTE_HANDLE_TYPE_SOCKET:
203: 		lNetworkEvents = dmn->dmn_network_events;
204: 		if (events & DISPATCH_MUXNOTE_EVENT_READ) {
205: 			lNetworkEvents &= ~FD_READ;
206: 		}
207: 		if (events & DISPATCH_MUXNOTE_EVENT_WRITE) {
208: 			lNetworkEvents &= ~FD_WRITE;
209: 		}
210: 		if (lNetworkEvents == dmn->dmn_network_events) {
211: 			break;
212: 		}
213: 		int iResult;
214: 		if (lNetworkEvents & (FD_READ | FD_WRITE)) {
215: 			iResult = WSAEventSelect((SOCKET)dmn->dmn_ident,
216: 					(WSAEVENT)dmn->dmn_event, lNetworkEvents);
217: 		} else {
218: 			lNetworkEvents = 0;
219: 			iResult = WSAEventSelect((SOCKET)dmn->dmn_ident, NULL, 0);
220: 		}
221: 		if (iResult != 0) {
222: 			DISPATCH_INTERNAL_CRASH(WSAGetLastError(), "WSAEventSelect");
223: 		}
224: 		dmn->dmn_network_events = lNetworkEvents;
225: 		if (!lNetworkEvents && dmn->dmn_threadpool_wait) {
226: 			SetThreadpoolWait(dmn->dmn_threadpool_wait, NULL, NULL);
227: 			WaitForThreadpoolWaitCallbacks(dmn->dmn_threadpool_wait,
228: 					/* fCancelPendingCallbacks */ FALSE);
229: 			CloseThreadpoolWait(dmn->dmn_threadpool_wait);
230: 			dmn->dmn_threadpool_wait = NULL;
231: 		}
232: 		break;
233: 	}
234: }
