279: static unsigned WINAPI
280: _dispatch_pipe_monitor_thread(void *context)
281: {
282: 	dispatch_muxnote_t dmn = (dispatch_muxnote_t)context;
283: 	HANDLE hPipe = (HANDLE)dmn->dmn_ident;
284: 	do {
