286: 		DWORD dwNumberOfBytesTransferred;
287: 		OVERLAPPED ov = {0};
288: 		BOOL bSuccess = ReadFile(hPipe, cBuffer, /* nNumberOfBytesToRead */ 0,
289: 				&dwNumberOfBytesTransferred, &ov);
290: 		DWORD dwBytesAvailable;
291: 		DWORD dwError = GetLastError();
292: 		if (!bSuccess && dwError == ERROR_IO_PENDING) {
293: 			bSuccess = GetOverlappedResult(hPipe, &ov,
294: 					&dwNumberOfBytesTransferred, /* bWait */ TRUE);
295: 			dwError = GetLastError();
296: 		}
297: 		if (bSuccess) {
298: 			bSuccess = PeekNamedPipe(hPipe, NULL, 0, NULL, &dwBytesAvailable,
299: 					NULL);
300: 			dwError = GetLastError();
301: 		}
302: 		if (bSuccess) {
303: 			if (dwBytesAvailable == 0) {
304: 				// This can happen with a zero-byte write. Try again.
305: 				continue;
306: 			}
307: 		} else if (dwError == ERROR_NO_DATA) {
308: 			// The pipe is nonblocking. Try again.
309: 			Sleep(0);
310: 			continue;
311: 		} else {
312: 			_dispatch_debug("pipe[0x%llx]: GetLastError() returned %lu",
313: 					(long long)hPipe, dwError);
314: 			if (dwError == ERROR_OPERATION_ABORTED) {
315: 				continue;
316: 			}
317: 			os_atomic_store(&dmn->dmn_stop, true, relaxed);
318: 			dwBytesAvailable = 0;
319: 		}
320: 
321: 		// Make sure the muxnote stays alive until the packet is dequeued
322: 		_dispatch_muxnote_retain(dmn);
323: 
324: 		// The lpOverlapped parameter does not actually need to point to an
325: 		// OVERLAPPED struct. It's really just a pointer to pass back to
326: 		// GetQueuedCompletionStatus().
327: 		bSuccess = PostQueuedCompletionStatus(hPort,
328: 				dwBytesAvailable, (ULONG_PTR)DISPATCH_PORT_PIPE_HANDLE_READ,
329: 				(LPOVERLAPPED)dmn);
330: 		if (!bSuccess) {
331: 			DISPATCH_INTERNAL_CRASH(GetLastError(),
332: 					"PostQueuedCompletionStatus");
333: 		}
334: 
335: 		// If data is written into the pipe and not read right away, ReadFile()
336: 		// will keep returning immediately and we'll flood the completion port.
337: 		// This event lets us synchronize with _dispatch_event_loop_drain() so
338: 		// that we only post events when it's ready for them.
339: 		WaitForSingleObject(dmn->dmn_event, INFINITE);
340: 	} while (!os_atomic_load(&dmn->dmn_stop, relaxed));
341: 	_dispatch_debug("pipe[0x%llx]: monitor exiting", (long long)hPipe);
342: 	return 0;
343: }
