345: static DWORD
346: _dispatch_pipe_write_availability(HANDLE hPipe)
347: {
348: 	IO_STATUS_BLOCK iosb;
349: 	FILE_PIPE_LOCAL_INFORMATION fpli;
350: 	NTSTATUS status = _dispatch_NtQueryInformationFile(hPipe, &iosb, &fpli,
351: 			sizeof(fpli), FilePipeLocalInformation);
352: 	if (!NT_SUCCESS(status)) {
353: 		return 1;
354: 	}
355: 	return fpli.WriteQuotaAvailable;
356: }
