358: static VOID CALLBACK
359: _dispatch_socket_callback(PTP_CALLBACK_INSTANCE inst, void *context,
360: 		PTP_WAIT pwa, TP_WAIT_RESULT res)
361: {
362: 	dispatch_muxnote_t dmn = (dispatch_muxnote_t)context;
363: 	SOCKET sock = (SOCKET)dmn->dmn_ident;
364: 	WSANETWORKEVENTS events;
365: 	if (WSAEnumNetworkEvents(sock, (WSAEVENT)dmn->dmn_event, &events) == 0) {
366: 		long lNetworkEvents = events.lNetworkEvents;
367: 		DWORD dwBytesAvailable = 1;
368: 		if (lNetworkEvents & FD_CLOSE) {
369: 			dwBytesAvailable = 0;
370: 		} else if (lNetworkEvents & FD_READ) {
371: 			ioctlsocket(sock, FIONREAD, &dwBytesAvailable);
372: 		}
373: 		if ((lNetworkEvents & FD_CLOSE) ||
374: 			((lNetworkEvents & FD_READ) && (dwBytesAvailable > 0))) {
375: 			_dispatch_muxnote_retain(dmn);
376: 			if (!PostQueuedCompletionStatus(hPort, dwBytesAvailable,
377: 					(ULONG_PTR)DISPATCH_PORT_SOCKET_READ, (LPOVERLAPPED)dmn)) {
378: 				DISPATCH_INTERNAL_CRASH(GetLastError(),
379: 						"PostQueuedCompletionStatus");
380: 			}
381: 		}
382: 		if ((lNetworkEvents & FD_CLOSE) || (lNetworkEvents & FD_WRITE)) {
383: 			_dispatch_muxnote_retain(dmn);
384: 			if (!PostQueuedCompletionStatus(hPort,
385: 					lNetworkEvents & FD_CLOSE ? 0 : 1,
386: 					(ULONG_PTR)DISPATCH_PORT_SOCKET_WRITE, (LPOVERLAPPED)dmn)) {
387: 				DISPATCH_INTERNAL_CRASH(GetLastError(),
388: 						"PostQueuedCompletionStatus");
389: 			}
390: 		}
391: 	} else {
392: 		_dispatch_debug("socket[0x%llx]: WSAEnumNetworkEvents() failed (%d)",
393: 				(long long)sock, WSAGetLastError());
394: 	}
395: 	SetThreadpoolWait(pwa, dmn->dmn_event, /* pftTimeout */ NULL);
396: }
397: 
398: static BOOL
399: _dispatch_io_trigger(dispatch_muxnote_t dmn)
400: {
401: 	BOOL bSuccess;
402: 	long lNetworkEvents;
403: 
404: 	switch (dmn->dmn_handle_type) {
405: 	case DISPATCH_MUXNOTE_HANDLE_TYPE_INVALID:
406: 		DISPATCH_INTERNAL_CRASH(0, "invalid handle");
407: 
408: 	case DISPATCH_MUXNOTE_HANDLE_TYPE_FILE:
409: 		_dispatch_muxnote_retain(dmn);
410: 		bSuccess = PostQueuedCompletionStatus(hPort, 0,
411: 			(ULONG_PTR)DISPATCH_PORT_FILE_HANDLE, (LPOVERLAPPED)dmn);
412: 		if (bSuccess == FALSE) {
413: 			DISPATCH_INTERNAL_CRASH(GetLastError(),
414: 				"PostQueuedCompletionStatus");
415: 		}
416: 		break;
417: 
418: 	case DISPATCH_MUXNOTE_HANDLE_TYPE_PIPE:
419: 		if ((dmn->dmn_events & DISPATCH_MUXNOTE_EVENT_READ) &&
420: 				!dmn->dmn_thread) {
421: 			dmn->dmn_thread = (HANDLE)_beginthreadex(/* security */ NULL,
422: 					/* stack_size */ 1, _dispatch_pipe_monitor_thread,
423: 					(void *)dmn, /* initflag */ 0, /* thrdaddr */ NULL);
424: 			if (!dmn->dmn_thread) {
425: 				DISPATCH_INTERNAL_CRASH(errno, "_beginthread");
426: 			}
427: 			dmn->dmn_event = CreateEventW(NULL, /* bManualReset */ FALSE,
428: 					/* bInitialState */ FALSE, NULL);
429: 			if (!dmn->dmn_event) {
430: 				DISPATCH_INTERNAL_CRASH(GetLastError(), "CreateEventW");
431: 			}
432: 		}
433: 		if (dmn->dmn_events & DISPATCH_MUXNOTE_EVENT_WRITE) {
434: 			_dispatch_muxnote_retain(dmn);
435: 			DWORD available;
436: 			if (dmn->dmn_events & DISPATCH_MUXNOTE_EVENT_READ) {
437: 				// We can't query a pipe which has a read source open on it
438: 				// because the ReadFile() in the background thread might cause
439: 				// NtQueryInformationFile() to block
440: 				available = 1;
441: 			} else {
442: 				available =
443: 					_dispatch_pipe_write_availability((HANDLE)dmn->dmn_ident);
444: 			}
445: 			bSuccess = PostQueuedCompletionStatus(hPort, available,
446: 					(ULONG_PTR)DISPATCH_PORT_PIPE_HANDLE_WRITE,
447: 					(LPOVERLAPPED)dmn);
448: 			if (bSuccess == FALSE) {
449: 				DISPATCH_INTERNAL_CRASH(GetLastError(),
450: 						"PostQueuedCompletionStatus");
451: 			}
452: 		}
453: 		break;
454: 
455: 	case DISPATCH_MUXNOTE_HANDLE_TYPE_SOCKET:
456: 		if (!dmn->dmn_event) {
457: 			dmn->dmn_event = CreateEventW(NULL, /* bManualReset */ FALSE,
458: 					/* bInitialState */ FALSE, NULL);
459: 			if (!dmn->dmn_event) {
460: 				DISPATCH_INTERNAL_CRASH(GetLastError(), "CreateEventW");
461: 			}
462: 		}
463: 		if (!dmn->dmn_threadpool_wait) {
464: 			dmn->dmn_threadpool_wait = CreateThreadpoolWait(
465: 					_dispatch_socket_callback, dmn,
466: 					/* PTP_CALLBACK_ENVIRON */ NULL);
467: 			if (!dmn->dmn_threadpool_wait) {
468: 				DISPATCH_INTERNAL_CRASH(GetLastError(), "CreateThreadpoolWait");
469: 			}
470: 			SetThreadpoolWait(dmn->dmn_threadpool_wait, dmn->dmn_event,
471: 					/* pftTimeout */ NULL);
472: 		}
473: 		lNetworkEvents = FD_CLOSE;
474: 		if (dmn->dmn_events & DISPATCH_MUXNOTE_EVENT_READ) {
475: 			lNetworkEvents |= FD_READ;
476: 		}
477: 		if (dmn->dmn_events & DISPATCH_MUXNOTE_EVENT_WRITE) {
478: 			lNetworkEvents |= FD_WRITE;
479: 		}
480: 		if (dmn->dmn_network_events != lNetworkEvents) {
481: 			if (WSAEventSelect((SOCKET)dmn->dmn_ident, (WSAEVENT)dmn->dmn_event,
482: 					lNetworkEvents) != 0) {
483: 				DISPATCH_INTERNAL_CRASH(WSAGetLastError(), "WSAEventSelect");
484: 			}
485: 			dmn->dmn_network_events = lNetworkEvents;
486: 		}
487: 		if (dmn->dmn_events & DISPATCH_MUXNOTE_EVENT_WRITE) {
488: 			// FD_WRITE is edge-triggered, not level-triggered, so it will only
489: 			// be signaled if the socket becomes writable after a send() fails
490: 			// with WSAEWOULDBLOCK. We can work around this by performing a
491: 			// zero-byte send(). If the socket is writable, the send() will
492: 			// succeed and we can immediately post a packet, and if it isn't, it
493: 			// will fail with WSAEWOULDBLOCK and WSAEventSelect() will report
494: 			// the next time it becomes available.
495: 			if (send((SOCKET)dmn->dmn_ident, "", 0, 0) == 0) {
496: 				_dispatch_muxnote_retain(dmn);
497: 				bSuccess = PostQueuedCompletionStatus(hPort, 1,
498: 						(ULONG_PTR)DISPATCH_PORT_SOCKET_WRITE,
499: 						(LPOVERLAPPED)dmn);
500: 				if (bSuccess == FALSE) {
501: 					DISPATCH_INTERNAL_CRASH(GetLastError(),
502: 							"PostQueuedCompletionStatus");
503: 				}
504: 			}
505: 		}
506: 		break;
507: 	}
508: 
509: 	return TRUE;
510: }
