512: DISPATCH_ALWAYS_INLINE
513: static inline enum _dispatch_muxnote_events
514: _dispatch_unote_required_events(dispatch_unote_t du)
515: {
516: 	switch (du._du->du_filter) {
517: 	case DISPATCH_EVFILT_CUSTOM_ADD:
518: 	case DISPATCH_EVFILT_CUSTOM_OR:
519: 	case DISPATCH_EVFILT_CUSTOM_REPLACE:
520: 		return 0;
521: 	case EVFILT_WRITE:
522: 		return DISPATCH_MUXNOTE_EVENT_WRITE;
523: 	default:
524: 		return DISPATCH_MUXNOTE_EVENT_READ;
525: 	}
526: }
