528: bool
529: _dispatch_unote_register_muxed(dispatch_unote_t du)
530: {
531: 	struct dispatch_muxnote_bucket_s *dmb;
532: 	dispatch_muxnote_t dmn;
533: 	enum _dispatch_muxnote_events events;
534: 
535: 	events = _dispatch_unote_required_events(du);
536: 
537: 	dmb = _dispatch_unote_muxnote_bucket(du._du->du_ident);
538: 	dmn = _dispatch_unote_muxnote_find(dmb, du._du->du_ident,
539: 		du._du->du_filter);
540: 	if (dmn) {
541: 		if (events & ~dmn->dmn_events) {
542: 			dmn->dmn_events |= events;
543: 			if (_dispatch_io_trigger(dmn) == FALSE) {
544: 				return false;
545: 			}
546: 		}
547: 	} else {
548: 		dmn = _dispatch_muxnote_create(du, events);
549: 		if (!dmn) {
550: 			return false;
551: 		}
552: 		if (_dispatch_io_trigger(dmn) == FALSE) {
553: 			_dispatch_muxnote_release(dmn);
554: 			return false;
555: 		}
556: 		LIST_INSERT_HEAD(dmb, dmn, dmn_list);
557: 	}
558: 
559: 	dispatch_unote_linkage_t dul = _dispatch_unote_get_linkage(du);
560: 	switch (dmn->dmn_handle_type) {
561: 	case DISPATCH_MUXNOTE_HANDLE_TYPE_INVALID:
562: 		DISPATCH_INTERNAL_CRASH(0, "invalid handle");
563: 
564: 	case DISPATCH_MUXNOTE_HANDLE_TYPE_FILE:
565: 	case DISPATCH_MUXNOTE_HANDLE_TYPE_PIPE:
566: 	case DISPATCH_MUXNOTE_HANDLE_TYPE_SOCKET:
567: 		if (events & DISPATCH_MUXNOTE_EVENT_READ) {
568: 			LIST_INSERT_HEAD(&dmn->dmn_readers_head, dul, du_link);
569: 		} else if (events & DISPATCH_MUXNOTE_EVENT_WRITE) {
570: 			LIST_INSERT_HEAD(&dmn->dmn_writers_head, dul, du_link);
571: 		}
572: 		break;
573: 	}
574: 
575: 	dul->du_muxnote = dmn;
576: 	_dispatch_unote_state_set(du, DISPATCH_WLH_ANON, DU_STATE_ARMED);
577: 
578: 	return true;
579: }
