581: void
582: _dispatch_unote_resume_muxed(dispatch_unote_t du)
583: {
584: 	dispatch_unote_linkage_t dul = _dispatch_unote_get_linkage(du);
585: 	dispatch_muxnote_t dmn = dul->du_muxnote;
586: 	dispatch_assert(_dispatch_unote_registered(du));
587: 	_dispatch_io_trigger(dmn);
588: }
