590: bool
591: _dispatch_unote_unregister_muxed(dispatch_unote_t du)
592: {
593: 	dispatch_unote_linkage_t dul = _dispatch_unote_get_linkage(du);
594: 	dispatch_muxnote_t dmn = dul->du_muxnote;
595: 
596: 	switch (dmn->dmn_handle_type) {
597: 	case DISPATCH_MUXNOTE_HANDLE_TYPE_INVALID:
598: 		DISPATCH_INTERNAL_CRASH(0, "invalid handle");
599: 
600: 	case DISPATCH_MUXNOTE_HANDLE_TYPE_FILE:
601: 	case DISPATCH_MUXNOTE_HANDLE_TYPE_PIPE:
602: 	case DISPATCH_MUXNOTE_HANDLE_TYPE_SOCKET:
603: 		LIST_REMOVE(dul, du_link);
604: 		_LIST_TRASH_ENTRY(dul, du_link);
605: 		break;
606: 	}
607: 	dul->du_muxnote = NULL;
608: 
609: 	enum _dispatch_muxnote_events disarmed = 0;
610: 	if (LIST_EMPTY(&dmn->dmn_readers_head)) {
611: 		disarmed |= DISPATCH_MUXNOTE_EVENT_READ;
612: 	}
613: 	if (LIST_EMPTY(&dmn->dmn_writers_head)) {
614: 		disarmed |= DISPATCH_MUXNOTE_EVENT_WRITE;
615: 	}
616: 	_dispatch_muxnote_disarm_events(dmn, disarmed);
617: 	if (!dmn->dmn_events) {
618: 		LIST_REMOVE(dmn, dmn_list);
619: 		_dispatch_muxnote_release(dmn);
620: 	}
621: 
622: 	_dispatch_unote_state_set(du, DU_STATE_UNREGISTERED);
623: 	return true;
624: }
