626: static void
627: _dispatch_event_merge_file_handle(dispatch_muxnote_t dmn)
628: {
629: 	dispatch_unote_linkage_t dul, dul_next;
630: 	LIST_FOREACH_SAFE(dul, &dmn->dmn_readers_head, du_link, dul_next) {
631: 		dispatch_unote_t du = _dispatch_unote_linkage_get_unote(dul);
632: 		// consumed by dux_merge_evt()
633: 		_dispatch_retain_unote_owner(du);
634: 		dispatch_assert(dux_needs_rearm(du._du));
635: 		_dispatch_unote_state_clear_bit(du, DU_STATE_ARMED);
636: 		os_atomic_store2o(du._dr, ds_pending_data, ~1, relaxed);
637: 		dux_merge_evt(du._du, EV_ADD | EV_ENABLE | EV_DISPATCH, 1, 0);
638: 	}
639: 	LIST_FOREACH_SAFE(dul, &dmn->dmn_writers_head, du_link, dul_next) {
640: 		dispatch_unote_t du = _dispatch_unote_linkage_get_unote(dul);
641: 		// consumed by dux_merge_evt()
642: 		_dispatch_retain_unote_owner(du);
643: 		dispatch_assert(dux_needs_rearm(du._du));
644: 		_dispatch_unote_state_clear_bit(du, DU_STATE_ARMED);
645: 		os_atomic_store2o(du._dr, ds_pending_data, ~1, relaxed);
646: 		dux_merge_evt(du._du, EV_ADD | EV_ENABLE | EV_DISPATCH, 1, 0);
647: 	}
648: 	// Retained when posting the completion packet
649: 	_dispatch_muxnote_release(dmn);
650: }
