652: static void
653: _dispatch_event_merge_pipe_handle_read(dispatch_muxnote_t dmn,
654: 		DWORD dwBytesAvailable)
655: {
656: 	dispatch_unote_linkage_t dul, dul_next;
657: 	LIST_FOREACH_SAFE(dul, &dmn->dmn_readers_head, du_link, dul_next) {
658: 		dispatch_unote_t du = _dispatch_unote_linkage_get_unote(dul);
659: 		// consumed by dux_merge_evt()
660: 		_dispatch_retain_unote_owner(du);
661: 		dispatch_unote_state_t du_state = _dispatch_unote_state(du);
662: 		du_state &= ~DU_STATE_ARMED;
663: 		uintptr_t data = dwBytesAvailable;
664: 		uint32_t flags;
665: 		if (dwBytesAvailable > 0) {
666: 			flags = EV_ADD | EV_ENABLE | EV_DISPATCH;
667: 		} else {
668: 			du_state |= DU_STATE_NEEDS_DELETE;
669: 			flags = EV_DELETE | EV_DISPATCH;
670: 		}
671: 		_dispatch_unote_state_set(du, du_state);
672: 		os_atomic_store2o(du._dr, ds_pending_data, ~data, relaxed);
673: 		dux_merge_evt(du._du, flags, data, 0);
674: 	}
675: 	SetEvent(dmn->dmn_event);
676: 	// Retained when posting the completion packet
677: 	_dispatch_muxnote_release(dmn);
678: }
