680: static void
681: _dispatch_event_merge_pipe_handle_write(dispatch_muxnote_t dmn,
682: 		DWORD dwBytesAvailable)
683: {
684: 	dispatch_unote_linkage_t dul, dul_next;
685: 	LIST_FOREACH_SAFE(dul, &dmn->dmn_writers_head, du_link, dul_next) {
686: 		dispatch_unote_t du = _dispatch_unote_linkage_get_unote(dul);
687: 		// consumed by dux_merge_evt()
688: 		_dispatch_retain_unote_owner(du);
689: 		_dispatch_unote_state_clear_bit(du, DU_STATE_ARMED);
690: 		uintptr_t data = dwBytesAvailable;
691: 		if (dwBytesAvailable > 0) {
692: 			os_atomic_store2o(du._dr, ds_pending_data, ~data, relaxed);
693: 		} else {
694: 			os_atomic_store2o(du._dr, ds_pending_data, 0, relaxed);
695: 		}
696: 		dux_merge_evt(du._du, EV_ADD | EV_ENABLE | EV_DISPATCH, data, 0);
697: 	}
698: 	// Retained when posting the completion packet
699: 	_dispatch_muxnote_release(dmn);
700: }
