707: 	dispatch_unote_state_t du_state = _dispatch_unote_state(du);
708: 	du_state &= ~DU_STATE_ARMED;
709: 	uintptr_t data = dwBytesAvailable;
710: 	uint32_t flags;
711: 	if (dwBytesAvailable > 0) {
712: 		flags = EV_ADD | EV_ENABLE | EV_DISPATCH;
713: 	} else {
714: 		du_state |= DU_STATE_NEEDS_DELETE;
715: 		flags = EV_DELETE | EV_DISPATCH;
716: 	}
717: 	_dispatch_unote_state_set(du, du_state);
718: 	os_atomic_store2o(du._dr, ds_pending_data, ~data, relaxed);
719: 	dux_merge_evt(du._du, flags, data, 0);
720: }
