795: void
796: _dispatch_event_loop_timer_arm(dispatch_timer_heap_t dth DISPATCH_UNUSED,
797: 		uint32_t tidx, dispatch_timer_delay_s range,
798: 		dispatch_clock_now_cache_t nows)
799: {
800: 	dispatch_windows_timeout_t timer;
801: 	FILETIME ftDueTime;
802: 	LARGE_INTEGER liTime;
803: 
804: 	switch (DISPATCH_TIMER_CLOCK(tidx)) {
805: 	case DISPATCH_CLOCK_WALL:
806: 		timer = &_dispatch_windows_timeout[DISPATCH_CLOCK_WALL];
807: 		liTime.QuadPart = range.delay +
808: 			_dispatch_time_now_cached(DISPATCH_TIMER_CLOCK(tidx), nows);
809: 		break;
810: 
811: 	case DISPATCH_CLOCK_UPTIME:
812: 	case DISPATCH_CLOCK_MONOTONIC:
813: 		timer = &_dispatch_windows_timeout[DISPATCH_TIMER_CLOCK(tidx)];
814: 		liTime.QuadPart = -((range.delay + 99) / 100);
815: 		break;
816: 	}
817: 
818: 	if (timer->pTimer == NULL) {
819: 		timer->pTimer = CreateThreadpoolTimer(_dispatch_timer_callback,
820: 			(LPVOID)timer->ullIdent, NULL);
821: 		if (timer->pTimer == NULL) {
822: 			DISPATCH_INTERNAL_CRASH(GetLastError(),
823: 				"CreateThreadpoolTimer");
824: 		}
825: 	}
826: 
827: 	ftDueTime.dwHighDateTime = liTime.HighPart;
828: 	ftDueTime.dwLowDateTime = liTime.LowPart;
829: 
830: 	SetThreadpoolTimer(timer->pTimer, &ftDueTime, /*msPeriod=*/0,
831: 		/*msWindowLength=*/0);
832: 	timer->bArmed = TRUE;
833: }
