251: static DWORD
252: _push_timer_resolution(DWORD ms)
253: {
254: 	MMRESULT res;
255: 	static dispatch_once_t once;
256: 
257: 	if (ms > 16) {
258: 		// only update timer resolution if smaller than default 15.6ms
259: 		// zero means not updated
260: 		return 0;
261: 	}
262: 
263: 	// aim for the best resolution we can accomplish
264: 	dispatch_once(&once, ^{
265: 		TIMECAPS tc;
266: 		if (timeGetDevCaps(&tc, sizeof(tc)) == MMSYSERR_NOERROR) {
267: 			best_resolution = min(max(tc.wPeriodMin, best_resolution),
268: 					tc.wPeriodMax);
269: 		}
270: 	});
271: 
272: 	res = timeBeginPeriod(best_resolution);
273: 	if (res == TIMERR_NOERROR) {
274: 		return best_resolution;
275: 	}
276: 	// zero means not updated
277: 	return 0;
278: }
