280: // match ms parameter to result from _push_timer_resolution
281: DISPATCH_ALWAYS_INLINE
282: static inline void
283: _pop_timer_resolution(DWORD ms)
284: {
285: 	if (ms) timeEndPeriod(ms);
286: }
