344: #pragma mark - ulock wrappers
345: #if HAVE_UL_COMPARE_AND_WAIT || HAVE_UL_UNFAIR_LOCK
346: 
347: // returns 0, ETIMEDOUT, ENOTEMPTY, EFAULT, EINTR
348: static int
349: _dlock_wait(uint32_t *uaddr, uint32_t val, uint32_t timeout, uint32_t flags)
350: {
351: 	for (;;) {
352: 		int rc = __ulock_wait(flags | ULF_NO_ERRNO, uaddr, val, timeout);
353: 		if (rc > 0) {
354: 			return ENOTEMPTY;
355: 		}
356: 		switch (-rc) {
357: 		case 0:
358: 			return 0;
359: 		case EINTR:
360: 			/*
361: 			 * if we have a timeout, we need to return for the caller to
362: 			 * recompute the new deadline, else just go back to wait.
363: 			 */
364: 			if (timeout == 0) {
365: 				continue;
366: 			}
367: 			DISPATCH_FALLTHROUGH;
368: 		case ETIMEDOUT:
369: 		case EFAULT:
370: 			return -rc;
371: 		default:
372: 			DISPATCH_INTERNAL_CRASH(-rc, "ulock_wait() failed");
373: 		}
374: 	}
375: }
376: 
377: static void
378: _dlock_wake(uint32_t *uaddr, uint32_t flags)
379: {
380: 	int rc = __ulock_wake(flags | ULF_NO_ERRNO, uaddr, 0);
381: 	if (rc == 0 || rc == -ENOENT) return;
382: 	DISPATCH_INTERNAL_CRASH(-rc, "ulock_wake() failed");
383: }
384: 
385: #endif // HAVE_UL_COMPARE_AND_WAIT || HAVE_UL_UNFAIR_LOCK
