429: DISPATCH_ALWAYS_INLINE
430: static inline int
431: _dispatch_futex(uint32_t *uaddr, int op, uint32_t val,
432: 		const struct timespec *timeout, uint32_t *uaddr2, uint32_t val3,
433: 		int opflags)
434: {
435: #if __linux__
436: 	return (int)syscall(SYS_futex, uaddr, op | opflags, val, timeout, uaddr2, val3);
437: #else
438: 	(void)val3;
439: 	return futex(uaddr, op | opflags, (int)val, timeout, uaddr2);
440: #endif
