443: // returns 0, ETIMEDOUT, EFAULT, EINTR, EWOULDBLOCK
444: DISPATCH_ALWAYS_INLINE
445: static inline int
446: _futex_blocking_op(uint32_t *uaddr, int futex_op, uint32_t val,
447: 		const struct timespec *timeout, int flags)
448: {
449: 	for (;;) {
450: 		int rc = _dispatch_futex(uaddr, futex_op, val, timeout, NULL, 0, flags);
451: 		if (!rc) {
452: 			return 0;
453: 		}
454: 		switch (errno) {
455: 		case EINTR:
456: 			/*
457: 			 * if we have a timeout, we need to return for the caller to
458: 			 * recompute the new deadline, else just go back to wait.
459: 			 */
460: 			if (timeout == 0) {
461: 				continue;
462: 			}
463: 			DISPATCH_FALLTHROUGH;
464: 		case ETIMEDOUT:
465: 		case EFAULT:
466: 		case EWOULDBLOCK:
467: 			return errno;
468: 		default:
469: 			DISPATCH_INTERNAL_CRASH(errno, "_futex_op() failed");
470: 		}
471: 	}
472: }
