482: _dispatch_futex_wake(uint32_t *uaddr, int wake, int opflags)
483: {
484: 	int rc = _dispatch_futex(uaddr, FUTEX_WAKE, (uint32_t)wake, NULL, NULL, 0,
485: 			opflags);
486: 	if (rc >= 0 || errno == ENOENT) return;
487: 	DISPATCH_INTERNAL_CRASH(errno, "_dlock_wake() failed");
488: }
