513: int
514: _dispatch_wait_on_address(uint32_t volatile *_address, uint32_t value,
515: 		dispatch_time_t timeout, dispatch_lock_options_t flags)
516: {
517: 	uint32_t *address = (uint32_t *)_address;
518: 	uint64_t nsecs = _dispatch_timeout(timeout);
519: 	if (nsecs == 0) {
520: 		return ETIMEDOUT;
521: 	}
522: #if HAVE_UL_COMPARE_AND_WAIT
523: 	uint64_t usecs = 0;
524: 	int rc;
525: 	if (nsecs == DISPATCH_TIME_FOREVER) {
526: 		return _dispatch_ulock_wait(address, value, 0, flags);
527: 	}
528: 	do {
529: 		usecs = howmany(nsecs, NSEC_PER_USEC);
530: 		if (usecs > UINT32_MAX) usecs = UINT32_MAX;
531: 		rc = _dispatch_ulock_wait(address, value, (uint32_t)usecs, flags);
532: 	} while (usecs == UINT32_MAX && rc == ETIMEDOUT &&
533: 			(nsecs = _dispatch_timeout(timeout)) != 0);
534: 	return rc;
535: #elif HAVE_FUTEX
536: 	(void)flags;
537: 	if (nsecs != DISPATCH_TIME_FOREVER) {
538: 		struct timespec ts = {
539: 			.tv_sec = (__typeof__(ts.tv_sec))(nsecs / NSEC_PER_SEC),
540: 			.tv_nsec = (__typeof__(ts.tv_nsec))(nsecs % NSEC_PER_SEC),
541: 		};
542: 		return _dispatch_futex_wait(address, value, &ts, FUTEX_PRIVATE_FLAG);
543: 	}
544: 	return _dispatch_futex_wait(address, value, NULL, FUTEX_PRIVATE_FLAG);
545: #elif defined(_WIN32)
546: 	// Round up to the nearest ms as `WaitOnAddress` takes a timeout in ms.
547: 	// Integral division will truncate, so make sure that we do the roundup.
548: 	DWORD dwMilliseconds =
549: 		nsecs == DISPATCH_TIME_FOREVER
550: 			? INFINITE : ((nsecs + 1000000) / 1000000);
551: 	if (dwMilliseconds == 0) return ETIMEDOUT;
552: 	return WaitOnAddress(address, &value, sizeof(value), dwMilliseconds) == TRUE;
553: #elif defined(__FreeBSD__)
554: 	(void)flags;
555: 	if (nsecs != DISPATCH_TIME_FOREVER) {
556: 		struct timespec ts = {
557: 			.tv_sec = (__typeof__(ts.tv_sec))(nsecs / NSEC_PER_SEC),
558: 			.tv_nsec = (__typeof__(ts.tv_nsec))(nsecs % NSEC_PER_SEC),
559: 		};
560: 		return _umtx_op((void*)address, UMTX_OP_WAIT_UINT, value, (void*)(uintptr_t)sizeof(struct timespec), (void*)&ts);
561: 	}
562: 	return _umtx_op((void*)address, UMTX_OP_WAIT_UINT, value, 0, 0);
563: #else
564: #error _dispatch_wait_on_address unimplemented for this platform
565: #endif
566: }
