621: #pragma mark - unfair lock
622: 
623: #if HAVE_UL_UNFAIR_LOCK
624: void
625: _dispatch_unfair_lock_lock_slow(dispatch_unfair_lock_t dul,
626: 		dispatch_lock_options_t flags)
627: {
628: 	dispatch_lock value_self = _dispatch_lock_value_for_self();
629: 	dispatch_lock old_value, new_value, next = value_self;
630: 	int rc;
631: 
632: 	for (;;) {
633: 		os_atomic_rmw_loop(&dul->dul_lock, old_value, new_value, acquire, {
634: 			if (likely(!_dispatch_lock_is_locked(old_value))) {
635: 				new_value = next;
636: 			} else {
637: 				new_value = old_value | DLOCK_WAITERS_BIT;
638: 				if (new_value == old_value) os_atomic_rmw_loop_give_up(break);
639: 			}
640: 		});
641: 		if (unlikely(_dispatch_lock_is_locked_by(old_value, value_self))) {
642: 			DISPATCH_CLIENT_CRASH(0, "trying to lock recursively");
643: 		}
644: 		if (new_value == next) {
645: 			return;
646: 		}
647: 		rc = _dispatch_unfair_lock_wait(&dul->dul_lock, new_value, 0, flags);
648: 		if (rc == ENOTEMPTY) {
649: 			next = value_self | DLOCK_WAITERS_BIT;
650: 		} else {
651: 			next = value_self;
652: 		}
653: 	}
654: }
655: #elif HAVE_FUTEX_PI
656: void
657: _dispatch_unfair_lock_lock_slow(dispatch_unfair_lock_t dul,
658: 		dispatch_lock_options_t flags)
