{
	// GetFileType() returns FILE_TYPE_PIPE for both pipes and sockets. We can
	// disambiguate by checking if PeekNamedPipe() fails with
	// ERROR_INVALID_FUNCTION.
	if (GetFileType(hFile) == FILE_TYPE_PIPE &&
